local ByName: { [string]: Pet } = {}
for _, pet in Pets do
	ByName[pet.Name] = pet
end

local GamePet = {}
GamePet.Pets = Pets
GamePet.ByName = ByName

function GamePet.get(name: string): Pet?
	return ByName[name]
end

function GamePet.names(): { string }
	local list = {}
	for _, pet in Pets do
		table.insert(list, pet.Name)
	end
	table.sort(list)
	return list
end

return GamePet
